    explanation: '危険物取扱者以外の者は、甲種又は乙種危険物取扱者の立会いがなければ危険物を取り扱うことができない。ここで押さえるべき核心は、丙種には立会権限がまったくないという点である。丙種はガソリン、灯油、軽油、第3石油類のうち重油と潤滑油及び引火点130度以上のもの、第4石油類、動植物油類という限られた品目を自ら取り扱うことはできるが、他人の作業に立ち会うことは認められていない。乙種は免状に指定された類についてのみ取扱いと立会いができ、甲種はすべての類について両方できる。なお、危険物取扱者が立ち会えば無資格者でも取扱いができるが、定期点検については丙種でも自ら実施でき、無資格者は危険物取扱者の立会いがあれば点検できるという別のルールがあるので区別しておきたい。\n\n【図解】免状の種類と権限\n　免状の種類｜取扱いができる範囲｜立会いの可否\n　甲種｜全類｜すべての類で可\n　乙種｜指定された類のみ｜指定された類のみ可\n　丙種｜ガソリン灯油軽油重油等の限定品目｜不可\n　⇒ 丙種は「自分でやるのはよいが人には立ち会えない」\n⚠ 乙種第4類は第4類だけ。他の類には立ち会えない。',
