    correctKey: 'C',
    explanation: '定期点検は、製造所等の位置、構造及び設備が技術上の基準に適合しているかを1年に1回以上自ら点検し、記録を作成して3年間保存する制度である。倍数にかかわらず対象となるのは、地下タンク貯蔵所、移動タンク貯蔵所、移送取扱所、そして地下タンクを有する製造所、給油取扱所、一般取扱所である。地下タンクは目視で漏れを確認できず、移動タンクは走行による振動を受けるため、危険性が高いとして一律に義務づけられている。倍数で区切られるのは製造所と一般取扱所が10以上、屋外貯蔵所が100以上、屋内貯蔵所が150以上、屋外タンク貯蔵所が200以上で、予防規程のしきい値と同じ数字が並ぶ。点検記録には点検した製造所等の名称、点検の方法と結果、年月日、実施者の氏名を記載する。\n\n【図解】倍数を問わず定期点検が必要な施設\n　施設｜理由｜備考\n　地下タンク貯蔵所｜漏れを目視できない｜すべて対象\n　移動タンク貯蔵所｜走行の振動を受ける｜すべて対象\n　移送取扱所｜配管が長距離｜すべて対象\n　地下タンクを有する製造所等｜地下部分が危険｜給油取扱所や一般取扱所も同様\n　⇒ 覚え方は「地下と移動と移送は無条件」\n⚠ 屋内タンク貯蔵所、簡易タンク貯蔵所、販売取扱所は定期点検の義務がない。',
