    explanation: '定期点検を行うことができるのは、危険物取扱者、危険物施設保安員、及び危険物取扱者の立会いを受けた者である。ここで丙種の扱いが独特で、丙種は他人の取扱作業には立ち会えないが、自らが取り扱える危険物についての定期点検は実施できる。逆に、無資格者であっても危険物取扱者が立ち会えば点検自体は可能である。頻度は原則1年に1回以上、記録の保存は原則3年間であるが、地下貯蔵タンクや二重殻タンクの漏れの点検など特例的に期間が異なるものもある。点検記録には、点検をした製造所等の名称、点検の方法と結果、点検年月日、点検を行った危険物取扱者若しくは危険物施設保安員又は立ち会った危険物取扱者の氏名を記載する。記録の未作成や未保存は、許可の取消し又は使用停止命令の事由となる重い違反である。\n\n【図解】定期点検を行える者\n　区分｜単独で点検できるか｜備考\n　甲種乙種危険物取扱者｜できる｜免状の類の範囲で\n　丙種危険物取扱者｜できる｜取り扱える品目の範囲で\n　危険物施設保安員｜できる｜免状は不要\n　上記以外の者｜危険物取扱者の立会いが必要｜立会いがあれば可\n　⇒ 点検は立会いで可、丙種も点検はできるという二点が急所\n⚠ 記録の未作成や未保存は許可の取消し又は使用停止命令の対象になる。',
