    explanation: '危険物保安監督者は、製造所等における危険物の取扱作業の保安に関する監督を行う者で、甲種又は乙種危険物取扱者であって、製造所等における危険物取扱いの実務経験が6か月以上ある者から選任する。丙種は選任できない。選任又は解任は遅滞なく市町村長等に届け出る。選任が必要な施設は、製造所、屋外タンク貯蔵所、給油取扱所、移送取扱所の四つが倍数を問わず必須で、その他の施設は取り扱う危険物の種類や倍数によって要否が分かれる。逆に移動タンク貯蔵所は、いかなる場合も危険物保安監督者を選任する必要がない唯一の施設として頻出である。危険物保安監督者は、火災等の災害が発生した場合に作業者を指揮し、消防機関への連絡や応急措置を講じる責務も負う。\n\n【図解】危険物保安監督者の要点\n　項目｜内容｜注意点\n　資格｜甲種又は乙種｜丙種は不可\n　実務経験｜6か月以上｜製造所等での取扱経験\n　常に選任が必要な施設｜製造所、屋外タンク貯蔵所、給油取扱所、移送取扱所｜倍数を問わない\n　選任不要な施設｜移動タンク貯蔵所｜唯一の例外\n　⇒ 届出は選任も解任も遅滞なく市町村長等へ\n⚠ 乙種第4類の者は、第4類の危険物を扱う施設の保安監督者にはなれる。',
