    correctKey: 'C',
    explanation: '指定数量以上の危険物は、原則として製造所等以外の場所で貯蔵し又は取り扱ってはならない。しかし工事現場での一時的な燃料保管など、短期間に限って必要となる場面があるため、所轄消防長又は消防署長の承認を受けた場合に限り、10日以内の期間に限って製造所等以外の場所で仮に貯蔵し又は取り扱うことが認められている。ここで重要なのは、承認を与えるのが市町村長等ではなく消防長又は消防署長である点と、期間が10日以内である点の二つである。これに対して、変更工事中の製造所等について工事に関係のない部分を使用したい場合に受けるのが仮使用の承認であり、こちらは市町村長等が承認する。仮貯蔵仮取扱いと仮使用は名前が似ているうえ、承認権者と対象が異なるので、必ず対比して覚えたい。\n\n【図解】仮貯蔵仮取扱いと仮使用の比較\n　項目｜仮貯蔵仮取扱い｜仮使用\n　対象｜製造所等以外の場所｜変更工事中の製造所等\n　手続｜承認｜承認\n　権者｜消防長又は消防署長｜市町村長等\n　期間｜10日以内｜工事期間中\n　⇒ 場所がまだ製造所等でないなら消防長、すでに製造所等なら市町村長等\n⚠ どちらも許可でも届出でもなく「承認」である点を落とさない。',
