    explanation: '混載の制限は、指定数量の10分の1を超える危険物を運搬する場合に適用される。したがって、指定数量の10分の1以下であれば、たとえば第1類と第4類を同一の車両に積んでも法令違反にはならない。この10分の1という基準は、運搬に関する規定の中でも特に問われやすい数値である。混載制限が適用される場合の可否は、第4類を軸にすると第2類、第3類、第5類が可、第1類と第6類が不可となる。他の類についても、第1類は第6類のみと混載可、第2類は第4類と第5類と混載可、第3類は第4類のみと混載可というように整理されている。なお、この規定は運搬の積載方法に関するものであり、移動タンク貯蔵所による移送や、貯蔵所における同時貯蔵の可否とは別の話である点に注意する。\n\n【図解】混載制限の適用範囲\n　場面｜混載制限｜根拠\n　指定数量の10分の1超の運搬｜適用される｜積載方法の基準\n　指定数量の10分の1以下の運搬｜適用されない｜少量の例外\n　移動タンク貯蔵所による移送｜適用されない｜運搬の規定ではない\n　貯蔵所における同時貯蔵｜別の規定による｜1m以上の間隔等\n　⇒ 混載制限は「運搬」かつ「10分の1超」のときの話\n⚠ 貯蔵の同時貯蔵禁止と運搬の混載制限は別制度なので混同しない。',
