    explanation: '製造所等の位置、構造又は設備を変更する場合、変更工事に係る部分以外の部分の全部又は一部について市町村長等の承認を受けたときは、完成検査を受ける前であってもその部分を仮に使用することができる。これを仮使用という。給油取扱所のように営業を継続しながら一部を改修する場面では、この制度がなければ工事期間中まったく営業できなくなってしまうため、実務上も重要な制度である。仮使用の承認を与えるのは許可権者である市町村長等であり、消防長又は消防署長ではない。これに対して、製造所等以外の場所で指定数量以上の危険物を10日以内の期間仮に貯蔵し又は取り扱う仮貯蔵仮取扱いの承認は、所轄消防長又は消防署長が与える。名称が似ている二つの承認について、対象と権者を対にして覚えることが必須である。\n\n【図解】二つの承認の使い分け\n　制度｜対象｜承認する者\n　仮使用｜変更工事中の製造所等のうち工事に係らない部分｜市町村長等\n　仮貯蔵仮取扱い｜製造所等以外の場所で10日以内｜消防長又は消防署長\n　⇒ すでに製造所等なら市町村長等、まだ製造所等でないなら消防長\n　⇒ どちらも許可でも届出でもなく承認である\n⚠ 仮使用に日数制限はなく、工事期間中が対象となる。',
