    explanation: '屋内貯蔵所の貯蔵倉庫は、原則として独立した専用の建築物とし、地盤面から軒までの高さが6m未満の平屋建で、床は地盤面より上に設ける。床面積は1000平方メートルを超えることができない。壁、柱及び床は耐火構造とし、はりは不燃材料で造り、延焼のおそれのある外壁は出入口以外の開口部を有しない壁とする。屋根は不燃材料で造るとともに金属板その他の軽量な不燃材料でふき、天井を設けない。これは爆発時に圧力を上方へ逃がすためである。液状の危険物を貯蔵する場合は、床を危険物が浸透しない構造とし、適当な傾斜をつけて貯留設備を設ける。数値としては1000平方メートル、軒高6m未満という二つが重要で、保有空地の判定に用いる耐火構造かどうかの区別ともあわせて整理しておきたい。\n\n【図解】貯蔵倉庫の主な基準\n　項目｜基準｜趣旨\n　床面積｜1000平方メートル以下｜規模の制限\n　軒までの高さ｜6m未満の平屋建｜消火活動の容易化\n　屋根｜軽量な不燃材料でふき天井を設けない｜爆発圧力を上へ逃がす\n　床｜浸透しない構造で傾斜と貯留設備｜漏えい油の回収\n　⇒ 1000平方メートルと6m未満をセットで暗記\n⚠ 第4石油類等では軒高20m未満の特例もあるが原則は6m未満である。',
