    correctKey: 'B',
    explanation: '保安に関する検査は、容量が1万kL以上の屋外タンク貯蔵所など政令で定める特定の屋外タンク貯蔵所及び移送取扱所について、市町村長等が定期に行う検査である。所有者等が自ら行う定期点検とは主体が異なり、行政庁が直接施設の状態を確認するという点で性格が大きく異なる。定期に行う定期保安検査のほか、不等沈下などの事由が生じた場合に受ける臨時保安検査もある。保安検査を受けないことは、無許可変更や完成検査前の使用、定期点検の未実施と並んで、許可の取消し又は使用停止命令の事由とされている重い違反である。乙種第4類の試験では細かい対象規模までは問われにくいが、行政庁が行う検査であること、受検義務違反が取消し事由になることの二点は押さえておきたい。\n\n【図解】定期点検と保安検査の比較\n　項目｜定期点検｜保安に関する検査\n　実施主体｜所有者等が自ら実施｜市町村長等が実施\n　対象｜多くの製造所等｜政令で定める屋外タンク貯蔵所と移送取扱所\n　違反の効果｜取消し又は使用停止｜取消し又は使用停止\n　⇒ 自主点検か行政検査かという主体の違いが本質\n⚠ どちらも懈怠すれば許可の取消しの事由になりうる。',
